INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G9.FOUNDA.SAFETY_ON_RAISED_PLATFOR.RAISED_PLATFORMS', 'PRE_.G9.FOUNDA.SAFETY_ON_RAISED_PLATFOR', 'pre_technical', 9, 'Name raised platforms and the risks of working on them', ARRAY['PRE_.G9.FOUNDA.SAFETY_ON_RAISED_PLATFOR.a', 'PRE_.G9.FOUNDA.SAFETY_ON_RAISED_PLATFOR.b']::text[], 'The child names ladders, step ladders, scaffolds and platforms, and the risks (falling, things falling on people below, a platform giving way), and says work at height is done only with a teacher or a trained adult and a helper. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G9.FOUNDA.SAFETY_ON_RAISED_PLATFOR.PLATFORM_RULES', 'PRE_.G9.FOUNDA.SAFETY_ON_RAISED_PLATFOR', 'pre_technical', 9, 'Give the safety rules for working on raised platforms: ladder angle and footing, three points of contact, no overreaching, top step, guard rails', ARRAY['PRE_.G9.FOUNDA.SAFETY_ON_RAISED_PLATFOR.c']::text[], 'Says a ladder stands on firm, level ground, footed by a helper, about 1 out for every 4 up; the climber keeps three points of contact and carries tools in a belt or bag, never leans out beyond the ladder, does not stand on the top steps of a step ladder, and that scaffolds have guard rails and toe boards; finds the unsafe act in a described job. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. The practical part (the drawing, the item made, the tool or computer used) is marked by the teacher with the KICD rubric, never by a tap.', '["pick the safe way to use a ladder or scaffold","find the unsafe act in a described job","work out where to place a ladder''s foot"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G9.FOUNDA.HANDLING_HAZARDOUS_SUBST.HAZARD_CLASSIFY', 'PRE_.G9.FOUNDA.HANDLING_HAZARDOUS_SUBST', 'pre_technical', 9, 'Name and classify hazardous substances', ARRAY['PRE_.G9.FOUNDA.HANDLING_HAZARDOUS_SUBST.a', 'PRE_.G9.FOUNDA.HANDLING_HAZARDOUS_SUBST.b']::text[], 'The child names hazardous substances at home and school (petrol, paraffin, bleach, acids, pesticides) and classifies them as flammable (catches fire), corrosive (eats away), toxic (poisons) or irritant, using the label. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G9.FOUNDA.HANDLING_HAZARDOUS_SUBST.HAZARD_HANDLING', 'PRE_.G9.FOUNDA.HANDLING_HAZARDOUS_SUBST', 'pre_technical', 9, 'Describe safe ways of handling hazardous substances', ARRAY['PRE_.G9.FOUNDA.HANDLING_HAZARDOUS_SUBST.c', 'PRE_.G9.FOUNDA.HANDLING_HAZARDOUS_SUBST.d']::text[], 'The child says to read the label, keep them in their own labelled containers out of reach of young children, never mix them, never eat or drink near them, wear gloves, use them in fresh air, and ask a teacher or adult for anything dangerous. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G9.FOUNDA.SELF_EXPLORATION_AND_CAR.TALENTS', 'PRE_.G9.FOUNDA.SELF_EXPLORATION_AND_CAR', 'pre_technical', 9, 'Relate talents to careers and tell ethical from unethical use', ARRAY['PRE_.G9.FOUNDA.SELF_EXPLORATION_AND_CAR.a', 'PRE_.G9.FOUNDA.SELF_EXPLORATION_AND_CAR.b', 'PRE_.G9.FOUNDA.SELF_EXPLORATION_AND_CAR.c', 'PRE_.G9.FOUNDA.SELF_EXPLORATION_AND_CAR.d']::text[], 'The child says talents grow by practice and guidance, links a talent to careers (drawing to design, running to athletics, kindness to nursing), and tells ethical use (honesty, fair play) from unethical (cheating, using a talent to harm). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G9.COMMUN.OBLIQUE_PROJECTION.OBLIQUE', 'PRE_.G9.COMMUN.OBLIQUE_PROJECTION', 'pre_technical', 9, 'Describe oblique projection', ARRAY['PRE_.G9.COMMUN.OBLIQUE_PROJECTION.a']::text[], 'The child says in oblique drawing the front face is drawn true shape and the depth is shown by sloping lines, usually at 45 degrees, and that in cabinet projection the depth is drawn half size while in cavalier it is full size. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G9.COMMUN.OBLIQUE_PROJECTION.OBLIQUE_DRAW', 'PRE_.G9.COMMUN.OBLIQUE_PROJECTION', 'pre_technical', 9, 'Give the steps to sketch and draw blocks in oblique: the front face true shape first, receding lines parallel at 45 degrees, half depth in cabinet, circles on the front face', ARRAY['PRE_.G9.COMMUN.OBLIQUE_PROJECTION.b', 'PRE_.G9.COMMUN.OBLIQUE_PROJECTION.c']::text[], 'Draws the front face true shape first, with the face that has circles or the most detail at the front; draws all receding lines parallel at 45 degrees; uses full depth for cavalier and half depth for cabinet; and finds the error in a described oblique drawing. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. The practical part (the drawing, the item made, the tool or computer used) is marked by the teacher with the KICD rubric, never by a tap.', '["put the drawing steps in order","work out a receding length","choose which face goes to the front"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G9.COMMUN.VISUAL_PROGRAMMING.VISUAL_APPS', 'PRE_.G9.COMMUN.VISUAL_PROGRAMMING', 'pre_technical', 9, 'Name application areas of visual programming', ARRAY['PRE_.G9.COMMUN.VISUAL_PROGRAMMING.a']::text[], 'The child names games, animations, simple phone apps, quizzes and controlling a device as uses of visual programming, and says blocks are joined so that the problem is solved step by step. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G9.COMMUN.VISUAL_PROGRAMMING.VP_APP_BUILD', 'PRE_.G9.COMMUN.VISUAL_PROGRAMMING', 'pre_technical', 9, 'Plan, build and test a simple visual program that solves a day-to-day problem: state the problem, plan the steps, use variables, reset at the start, test with right and wrong inputs', ARRAY['PRE_.G9.COMMUN.VISUAL_PROGRAMMING.b']::text[], 'States the problem and plans the steps before dragging blocks; uses a variable to keep a value such as a score, sets it to its start value when the green flag is clicked, and tests with right answers, wrong answers and unusual inputs, fixing the bugs found. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. The practical part (the drawing, the item made, the tool or computer used) is marked by the teacher with the KICD rubric, never by a tap.', '["put the app-building steps in order","say what is missing from a described program","choose how to test a program"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G9.MATERI.WOOD.WOOD_TYPES', 'PRE_.G9.MATERI.WOOD', 'pre_technical', 9, 'Classify wood and match types to uses', ARRAY['PRE_.G9.MATERI.WOOD.a', 'PRE_.G9.MATERI.WOOD.c']::text[], 'The child says hardwoods (mahogany, mvule, teak) come from broad-leaved trees that grow slowly, softwoods (pine, cypress) come from cone-bearing trees that grow faster, and manufactured boards (plywood, blockboard, chipboard) are made from wood layers or chips, and matches furniture, doors and building to them. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G9.MATERI.WOOD.WOOD_PREP', 'PRE_.G9.MATERI.WOOD', 'pre_technical', 9, 'Describe the preparation of wood for use', ARRAY['PRE_.G9.MATERI.WOOD.b']::text[], 'The child says logs are sawn into planks, the planks are seasoned (dried) so they do not warp or rot, then planed smooth and treated with a preservative or varnish. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G9.MATERI.HANDLING_WASTE_MATERIALS.WASTE', 'PRE_.G9.MATERI.HANDLING_WASTE_MATERIALS', 'pre_technical', 9, 'Name and handle waste materials safely', ARRAY['PRE_.G9.MATERI.HANDLING_WASTE_MATERIALS.a', 'PRE_.G9.MATERI.HANDLING_WASTE_MATERIALS.b', 'PRE_.G9.MATERI.HANDLING_WASTE_MATERIALS.c']::text[], 'The child names organic, plastic, metal, glass, paper and electronic waste, says to sort it, reduce, reuse and recycle, compost organic waste, and never burn plastic or leave sharp or hazardous waste where people can touch it. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G9.TOOLS_.HOLDING_TOOLS.HOLDING_TOOLS', 'PRE_.G9.TOOLS_.HOLDING_TOOLS', 'pre_technical', 9, 'Name holding tools and choose one for a task', ARRAY['PRE_.G9.TOOLS_.HOLDING_TOOLS.a', 'PRE_.G9.TOOLS_.HOLDING_TOOLS.b', 'PRE_.G9.TOOLS_.HOLDING_TOOLS.d']::text[], 'The child names the bench vice, G-clamp, hand vice, pliers and tongs, and says holding tools keep the work still so it can be cut or drilled safely, and that they are cleaned and oiled after use. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G9.TOOLS_.HOLDING_TOOLS.HOLD_USE', 'PRE_.G9.TOOLS_.HOLDING_TOOLS', 'pre_technical', 9, 'Give the correct way to use holding tools: work low in the vice, soft packing for finished work, clamp work for drilling, support long work', ARRAY['PRE_.G9.TOOLS_.HOLDING_TOOLS.c']::text[], 'Says to hold work low in the vice so it does not vibrate or bend, to put soft packing between steel jaws and finished work, to clamp work for drilling rather than holding it by hand, and to support the free end of long work; finds the wrong set-up in a described job. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. The practical part (the drawing, the item made, the tool or computer used) is marked by the teacher with the KICD rubric, never by a tap.', '["pick the right way to hold the work","find the mistake in a described set-up","say why a holding rule matters"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G9.TOOLS_.DRIVING_TOOLS.DRIVING_TOOLS', 'PRE_.G9.TOOLS_.DRIVING_TOOLS', 'pre_technical', 9, 'Name driving tools and choose one for a task', ARRAY['PRE_.G9.TOOLS_.DRIVING_TOOLS.a', 'PRE_.G9.TOOLS_.DRIVING_TOOLS.b', 'PRE_.G9.TOOLS_.DRIVING_TOOLS.d']::text[], 'The child says a hammer drives nails, a mallet drives chisels, a screwdriver drives screws (flat or cross head to match the screw), and a spanner turns nuts and bolts, and that tools are kept clean and stored safely. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G9.TOOLS_.DRIVING_TOOLS.DRIVE_USE', 'PRE_.G9.TOOLS_.DRIVING_TOOLS', 'pre_technical', 9, 'Give the correct way to use driving tools: hammer grip and starting a nail, screwdriver that fills the slot, spanner of the right size pulled towards you', ARRAY['PRE_.G9.TOOLS_.DRIVING_TOOLS.c']::text[], 'Says to hold a hammer near the end of the handle and start a nail with light taps before moving the fingers away, to use a screwdriver whose blade fills the slot, to use a spanner that fits the nut exactly and pull it towards you; finds the mistake in a described job. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. The practical part (the drawing, the item made, the tool or computer used) is marked by the teacher with the KICD rubric, never by a tap.', '["pick the right way to use a driving tool","find the mistake in a described job","say why a rule matters"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G9.TOOLS_.PROJECT.PROJECT_STEPS', 'PRE_.G9.TOOLS_.PROJECT', 'pre_technical', 9, 'Put the steps of a project in order', ARRAY['PRE_.G9.TOOLS_.PROJECT.a', 'PRE_.G9.TOOLS_.PROJECT.b']::text[], 'The child says a project starts by identifying a problem, then selecting an item to make, planning, making it from local materials, testing it and reporting what was learnt. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G9.TOOLS_.PROJECT.PROJECT_PLAN', 'PRE_.G9.TOOLS_.PROJECT', 'pre_technical', 9, 'Plan and evaluate the making of a project item: sketch and working drawing, materials list and cost, order of making, testing and evaluation against the problem', ARRAY['PRE_.G9.TOOLS_.PROJECT.c', 'PRE_.G9.TOOLS_.PROJECT.d']::text[], 'Says that making begins with a sketch and a working drawing with sizes, a materials and cost list, and an order of operations (mark, cut, join, sand, finish last); and that the item is tested and evaluated against the problem it was made to solve, with improvements named. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. The practical part (the drawing, the item made, the tool or computer used) is marked by the teacher with the KICD rubric, never by a tap.', '["put the making steps in order","say what a plan is missing","judge an item against the problem"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G9.ENTREP.FINANCIAL_SERVICES.FIN_TYPES', 'PRE_.G9.ENTREP.FINANCIAL_SERVICES', 'pre_technical', 9, 'Name and classify financial institutions in Kenya', ARRAY['PRE_.G9.ENTREP.FINANCIAL_SERVICES.a', 'PRE_.G9.ENTREP.FINANCIAL_SERVICES.b']::text[], 'The child names commercial banks, microfinance institutions, SACCOs, insurance companies and mobile money providers as financial institutions, and says the Central Bank of Kenya supervises the banks. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G9.ENTREP.FINANCIAL_SERVICES.FIN_SERVICES', 'PRE_.G9.ENTREP.FINANCIAL_SERVICES', 'pre_technical', 9, 'Name the services financial institutions offer', ARRAY['PRE_.G9.ENTREP.FINANCIAL_SERVICES.c', 'PRE_.G9.ENTREP.FINANCIAL_SERVICES.d']::text[], 'The child names savings, loans, insurance, money transfer and payments as services, and says a loan must be repaid with interest and savings should be kept for planned needs. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G9.ENTREP.GOVERNMENT_AND_BUSINESS.GOV_BUSINESS', 'PRE_.G9.ENTREP.GOVERNMENT_AND_BUSINESS', 'pre_technical', 9, 'Say why and how government is involved in business', ARRAY['PRE_.G9.ENTREP.GOVERNMENT_AND_BUSINESS.a', 'PRE_.G9.ENTREP.GOVERNMENT_AND_BUSINESS.b']::text[], 'The child says government protects customers, collects tax, sets standards and licences, and helps business with roads, power and training, and that businesses must follow the law. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G9.ENTREP.GOVERNMENT_AND_BUSINESS.TAXES', 'PRE_.G9.ENTREP.GOVERNMENT_AND_BUSINESS', 'pre_technical', 9, 'Name types of taxes and e-Government services', ARRAY['PRE_.G9.ENTREP.GOVERNMENT_AND_BUSINESS.c', 'PRE_.G9.ENTREP.GOVERNMENT_AND_BUSINESS.d']::text[], 'The child names income tax (PAYE), value added tax (VAT), customs duty and excise duty, says taxes pay for public services, and names eCitizen and the KRA online service as e-Government services. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G9.ENTREP.BUSINESS_PLAN.BUSINESS_PLAN', 'PRE_.G9.ENTREP.BUSINESS_PLAN', 'pre_technical', 9, 'Name the importance and components of a business plan', ARRAY['PRE_.G9.ENTREP.BUSINESS_PLAN.a', 'PRE_.G9.ENTREP.BUSINESS_PLAN.b']::text[], 'The child says a business plan guides the owner, helps to get a loan and measures progress, and names the business idea, the market, the marketing plan, the people and the money plan (costs and expected income) as components. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G9.ENTREP.BUSINESS_PLAN.BP_TEMPLATE', 'PRE_.G9.ENTREP.BUSINESS_PLAN', 'pre_technical', 9, 'Fill in a business plan template for a small project: description, market and competitors, start-up capital, projected sales, costs and profit, executive summary written last', ARRAY['PRE_.G9.ENTREP.BUSINESS_PLAN.c']::text[], 'Fills each part of a simple template: the business description, the market and the competitors named, start-up capital (equipment, licence and first stock), projected sales, costs and profit (sales - costs), and the executive summary, written last though placed first. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. The practical part (the drawing, the item made, the tool or computer used) is marked by the teacher with the KICD rubric, never by a tap.', '["say what goes in a part of the template","work out a projected profit","find what is missing from a filled-in plan"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
