INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.FOUNDA.SAFETY_ON_RAISED_PLATFOR.RAISED_PLATFORMS.M_PT9_RP_SAFE', 'PRET.G9.FOUNDA.SAFETY_ON_RAISED_PLATFOR.RAISED_PLATFORMS', 'Thinks a learner can climb and work on a raised platform alone.', '{"question":"Who should work on a raised platform?","wrong_answer":"A learner alone","correct_answer":"A trained adult with a helper"}'::jsonb, 'Climbing trees and walls at home feels normal and safe to the learner.', 'Offer "A learner alone" next to the right answer and ask the question again in a new situation.', 'Explain that work at height is done by trained adults with a helper; learners do not climb to work.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.FOUNDA.SAFETY_ON_RAISED_PLATFOR.RAISED_PLATFORMS.M_PT9_RP_RISK', 'PRET.G9.FOUNDA.SAFETY_ON_RAISED_PLATFOR.RAISED_PLATFORMS', 'Names a small discomfort instead of falling as the main risk of working at height.', '{"question":"What is the main risk when working on a ladder?","wrong_answer":"Getting paint on your clothes","correct_answer":"Falling, or dropping tools on people below"}'::jsonb, 'The learner thinks of small discomforts and does not picture a fall.', 'Offer "Getting paint on your clothes" beside "Falling, or dropping tools on people below" and ask the child to choose.', 'Show how a fall of even 2 m can cause serious injury; list falls, falling objects and collapse as the main risks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.FOUNDA.SAFETY_ON_RAISED_PLATFOR.RAISED_PLATFORMS.M_PT9_RP_TYPE', 'PRET.G9.FOUNDA.SAFETY_ON_RAISED_PLATFOR.RAISED_PLATFORMS', 'Thinks only scaffolds are raised platforms, not ladders, trestles or a chair used to reach high.', '{"question":"Kamau stands on a chair to fix a curtain. Is he on a raised platform?","wrong_answer":"No, only scaffolds are raised platforms","correct_answer":"Yes, and a chair is an unsafe one"}'::jsonb, 'Only scaffolds at building sites look like "platforms" to the learner.', 'Offer "No, only scaffolds are raised platforms" beside "Yes, and a chair is an unsafe one" and ask the child to choose.', 'List what people stand on to reach high: ladders, step ladders, trestles, scaffolds, roofs, and unsafe ones such as chairs and boxes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.FOUNDA.SAFETY_ON_RAISED_PLATFOR.PLATFORM_RULES.M_PT9_PR_ANGLE', 'PRET.G9.FOUNDA.SAFETY_ON_RAISED_PLATFOR.PLATFORM_RULES', 'Stands a ladder nearly upright against the wall, or very flat, instead of about 1 out for every 4 up.', '{"question":"A ladder reaches 4 m up a wall. About how far from the wall should its foot be?","wrong_answer":"As close to the wall as possible","correct_answer":"About 1 m out (1 out for every 4 up)"}'::jsonb, 'An upright ladder feels closer to the work and so safer.', 'Offer "As close to the wall as possible" beside "About 1 m out (1 out for every 4 up)" and ask the child to choose.', 'Lay a ladder on the ground and mark 4 along and 1 across; stand it against a low wall with the teacher and see the angle. Too upright tips back; too flat slides out.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.FOUNDA.SAFETY_ON_RAISED_PLATFOR.PLATFORM_RULES.M_PT9_PR_OVERREACH', 'PRET.G9.FOUNDA.SAFETY_ON_RAISED_PLATFOR.PLATFORM_RULES', 'Leans out sideways from a ladder to reach a spot instead of moving the ladder.', '{"question":"The spot to paint is beyond arm''s reach from the ladder. What do you do?","wrong_answer":"Lean out to reach it","correct_answer":"Climb down and move the ladder"}'::jsonb, 'Climbing down and moving feels slow when the spot is nearly in reach.', 'Offer "Lean out to reach it" beside "Climb down and move the ladder" and ask the child to choose.', 'Show how the weight moves outside the ladder and tips it; agree: belt buckle stays between the stiles.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.FOUNDA.SAFETY_ON_RAISED_PLATFOR.PLATFORM_RULES.M_PT9_PR_TOP_STEP', 'PRET.G9.FOUNDA.SAFETY_ON_RAISED_PLATFOR.PLATFORM_RULES', 'Stands on the top step of a step ladder to reach higher.', '{"question":"A step ladder is a little too short. What should you do?","wrong_answer":"Stand on the top step","correct_answer":"Get a taller ladder; do not stand on the top steps"}'::jsonb, 'The top step looks flat and solid like the others.', 'Offer "Stand on the top step" beside "Get a taller ladder; do not stand on the top steps" and ask the child to choose.', 'Show the ladder label: there is nothing to hold above the top step, so balance is lost. Use the right height of ladder.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.FOUNDA.SAFETY_ON_RAISED_PLATFOR.PLATFORM_RULES.M_PT9_PR_CONTACT', 'PRET.G9.FOUNDA.SAFETY_ON_RAISED_PLATFOR.PLATFORM_RULES', 'Climbs a ladder holding tools in both hands.', '{"question":"How should you climb a ladder when you need tools at the top?","wrong_answer":"Holding the tools in both hands","correct_answer":"Tools in a belt or bag, keeping three points of contact"}'::jsonb, 'Carrying the tools by hand is the quickest way up.', 'Offer "Holding the tools in both hands" beside "Tools in a belt or bag, keeping three points of contact" and ask the child to choose.', 'Practise on the bottom rung: two hands and a foot, or two feet and a hand, always touching the ladder; tools go in a belt or are passed up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.FOUNDA.SAFETY_ON_RAISED_PLATFOR.PLATFORM_RULES.M_PT9_PR_FOOTING', 'PRET.G9.FOUNDA.SAFETY_ON_RAISED_PLATFOR.PLATFORM_RULES', 'Stands a ladder on a box or bricks to make it taller, or on soft ground.', '{"question":"Where should a ladder stand?","wrong_answer":"On a box or bricks to make it taller","correct_answer":"On firm, level ground, held at the foot by a helper"}'::jsonb, 'Raising the ladder seems a clever way to gain height.', 'Offer "On a box or bricks to make it taller" beside "On firm, level ground, held at the foot by a helper" and ask the child to choose.', 'Show how a box or soft soil shifts under weight; use firm level ground and a helper footing the ladder.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.FOUNDA.SAFETY_ON_RAISED_PLATFOR.RAISED_PLATFORMS.M_PT9_RP_BELOW', 'PRET.G9.FOUNDA.SAFETY_ON_RAISED_PLATFOR.RAISED_PLATFORMS', 'Thinks only the worker at height is at risk, not people below.', '{"question":"A worker on a scaffold drops a hammer. Who is at risk?","wrong_answer":"Only the worker","correct_answer":"People below, who can be hit by falling objects"}'::jsonb, 'The learner pictures the danger only where the worker is.', 'Offer "Only the worker" beside "People below, who can be hit by falling objects" and ask the child to choose.', 'Mark a no-go area under a ladder or scaffold; explain toe boards and helmets.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.FOUNDA.HANDLING_HAZARDOUS_SUBST.HAZARD_CLASSIFY.M_PT9_HC_FLAMMABLE', 'PRET.G9.FOUNDA.HANDLING_HAZARDOUS_SUBST.HAZARD_CLASSIFY', 'Mixes up flammable (catches fire easily) and corrosive (eats away skin and metal).', '{"question":"Which word means catches fire easily?","wrong_answer":"Corrosive","correct_answer":"Flammable"}'::jsonb, 'Flammable and corrosive are long new words learnt in the same lesson.', 'Offer "Corrosive" next to the right answer and ask the question again in a new situation.', 'Match each word to its symbol: a flame for flammable, a hand and metal being eaten for corrosive.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.FOUNDA.HANDLING_HAZARDOUS_SUBST.HAZARD_CLASSIFY.M_PT9_HC_CORROSIVE', 'PRET.G9.FOUNDA.HANDLING_HAZARDOUS_SUBST.HAZARD_CLASSIFY', 'Mixes up corrosive and toxic.', '{"question":"Which word means eats away skin and metal?","wrong_answer":"Toxic","correct_answer":"Corrosive"}'::jsonb, 'Both words describe harm to the body, so they blur together.', 'Offer "Toxic" next to the right answer and ask the question again in a new situation.', 'Corrosive burns and eats away (acid, bleach); toxic poisons when swallowed, breathed or absorbed (pesticides).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.FOUNDA.HANDLING_HAZARDOUS_SUBST.HAZARD_CLASSIFY.M_PT9_HC_PETROL', 'PRET.G9.FOUNDA.HANDLING_HAZARDOUS_SUBST.HAZARD_CLASSIFY', 'Thinks petrol is safe because it is used every day.', '{"question":"How is petrol classified?","wrong_answer":"Safe, because cars use it every day","correct_answer":"Flammable"}'::jsonb, 'Petrol is used every day in cars and boda bodas, so it seems safe.', 'Offer "Safe, because cars use it every day" beside "Flammable" and ask the child to choose.', 'Show the flame symbol on a fuel container; petrol vapour catches fire from a spark or cigarette.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.FOUNDA.HANDLING_HAZARDOUS_SUBST.HAZARD_HANDLING.M_PT9_HH_LABEL', 'PRET.G9.FOUNDA.HANDLING_HAZARDOUS_SUBST.HAZARD_HANDLING', 'Opens and uses a substance without reading the label.', '{"question":"What should you do before using a substance?","wrong_answer":"Open it at once","correct_answer":"Read the label"}'::jsonb, 'The learner thinks they already know what is in a familiar container.', 'Offer "Open it at once" next to the right answer and ask the question again in a new situation.', 'Read a label aloud: hazard, how to use, protective wear, first aid, storage. Make "read the label" the first step.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.FOUNDA.HANDLING_HAZARDOUS_SUBST.HAZARD_HANDLING.M_PT9_HH_MIX', 'PRET.G9.FOUNDA.HANDLING_HAZARDOUS_SUBST.HAZARD_HANDLING', 'Mixes two cleaners, such as bleach and an acid toilet cleaner, to make them stronger.', '{"question":"What should you do with two cleaners?","wrong_answer":"Mix them to be stronger","correct_answer":"Never mix them"}'::jsonb, 'Two cleaners together sound twice as strong.', 'Offer "Mix them to be stronger" next to the right answer and ask the question again in a new situation.', 'Explain that some mixtures (such as bleach with an acid toilet cleaner) give off a poisonous gas; never mix. Not demonstrated.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.FOUNDA.HANDLING_HAZARDOUS_SUBST.HAZARD_HANDLING.M_PT9_HH_STORE', 'PRET.G9.FOUNDA.HANDLING_HAZARDOUS_SUBST.HAZARD_HANDLING', 'Stores paraffin or chemicals in drink bottles.', '{"question":"How should paraffin be stored?","wrong_answer":"In a drink bottle on the table","correct_answer":"In a labelled container out of reach"}'::jsonb, 'Drink bottles are the containers to hand at home.', 'Offer "In a drink bottle on the table" next to the right answer and ask the question again in a new situation.', 'Show why a child may drink paraffin from a soda bottle; store in the original labelled container, locked and out of reach.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.FOUNDA.HANDLING_HAZARDOUS_SUBST.HAZARD_CLASSIFY.M_PT9_HC_HOME_SAFE', 'PRET.G9.FOUNDA.HANDLING_HAZARDOUS_SUBST.HAZARD_CLASSIFY', 'Thinks products sold for home use, such as bleach, are not hazardous.', '{"question":"Bleach is used at home for cleaning. Is it hazardous?","wrong_answer":"No, home products are safe","correct_answer":"Yes, it is corrosive and harmful if swallowed or splashed in the eyes"}'::jsonb, 'Things sold in shops for the home seem tested and safe.', 'Offer "No, home products are safe" beside "Yes, it is corrosive and harmful if swallowed or splashed in the eyes" and ask the child to choose.', 'Read the label on a bleach bottle with the class: the hazard symbol and warnings are printed there.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.FOUNDA.HANDLING_HAZARDOUS_SUBST.HAZARD_CLASSIFY.M_PT9_HC_SKULL', 'PRET.G9.FOUNDA.HANDLING_HAZARDOUS_SUBST.HAZARD_CLASSIFY', 'Reads the skull-and-crossbones symbol as meaning "catches fire".', '{"question":"What does the skull-and-crossbones symbol on a container mean?","wrong_answer":"It catches fire easily","correct_answer":"Toxic: it can poison if swallowed, breathed in or on the skin"}'::jsonb, 'The learner knows the symbol means danger but not which kind.', 'Offer "It catches fire easily" beside "Toxic: it can poison if swallowed, breathed in or on the skin" and ask the child to choose.', 'Match each hazard symbol (flame, skull, corrosion, exclamation mark, environment) to its meaning and an example.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.FOUNDA.HANDLING_HAZARDOUS_SUBST.HAZARD_HANDLING.M_PT9_HH_PPE', 'PRET.G9.FOUNDA.HANDLING_HAZARDOUS_SUBST.HAZARD_HANDLING', 'Handles pesticide without protective clothing, thinking washing afterwards is enough.', '{"question":"A farmer mixes pesticide for spraying. What should he wear?","wrong_answer":"Nothing special, if he washes afterwards","correct_answer":"Gloves, a mask, boots and long sleeves, then wash afterwards"}'::jsonb, 'The harm is not seen at once, so protection seems unnecessary.', 'Offer "Nothing special, if he washes afterwards" beside "Gloves, a mask, boots and long sleeves, then wash afterwards" and ask the child to choose.', 'Read the protective wear section of a pesticide label; explain that some poisons pass through the skin and lungs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.FOUNDA.SELF_EXPLORATION_AND_CAR.TALENTS.M_PT9_TA_GROW', 'PRET.G9.FOUNDA.SELF_EXPLORATION_AND_CAR.TALENTS', 'Thinks talents need no practice.', '{"question":"How do talents grow?","wrong_answer":"Without any effort","correct_answer":"By practice and guidance"}'::jsonb, 'Talented people seem born ready, so practice looks unnecessary.', 'Offer "Without any effort" next to the right answer and ask the question again in a new situation.', 'Tell the story of a local footballer or musician: years of practice and coaching. Plan one way to practise a talent weekly.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.FOUNDA.SELF_EXPLORATION_AND_CAR.TALENTS.M_PT9_TA_ETHIC', 'PRET.G9.FOUNDA.SELF_EXPLORATION_AND_CAR.TALENTS', 'Thinks using a talent to do other learners'' assessed work for money is an ethical use.', '{"question":"A learner who draws well is paid to do classmates'' art homework. Is this an ethical use of the talent?","wrong_answer":"Yes, he earns money from his talent","correct_answer":"No, it is cheating; he could tutor them or sell his own art"}'::jsonb, 'Earning from a talent feels good whatever the use.', 'Offer "Yes, he earns money from his talent" beside "No, it is cheating; he could tutor them or sell his own art" and ask the child to choose.', 'Sort uses of talents into ethical (fair, honest, helps others) and unethical (cheating, harming, deceiving).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.FOUNDA.SELF_EXPLORATION_AND_CAR.TALENTS.M_PT9_TA_CAREER', 'PRET.G9.FOUNDA.SELF_EXPLORATION_AND_CAR.TALENTS', 'Links a talent for drawing to a career that does not use it.', '{"question":"Which career links best to a talent for drawing?","wrong_answer":"Driving","correct_answer":"Design, architecture or art"}'::jsonb, 'The learner links careers to the jobs they see most, not to talents.', 'Offer "Driving" beside "Design, architecture or art" and ask the child to choose.', 'Make a talent and career web: drawing leads to design, architecture, engineering drawing, art.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.FOUNDA.SELF_EXPLORATION_AND_CAR.TALENTS.M_PT9_TA_ONE_ONLY', 'PRET.G9.FOUNDA.SELF_EXPLORATION_AND_CAR.TALENTS', 'Thinks a person has only one talent and must choose a career from it alone.', '{"question":"Achieng sings well and is good at mathematics. What should guide her career choice?","wrong_answer":"Only singing, because a person has one talent","correct_answer":"All her talents, abilities and interests, with advice from teachers and family"}'::jsonb, 'The learner hears people described by one talent ("the singer").', 'Offer "Only singing, because a person has one talent" beside "All her talents, abilities and interests, with advice from teachers and family" and ask the child to choose.', 'List several talents and abilities for one person; show careers that use more than one (sound engineering uses music and mathematics).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.COMMUN.OBLIQUE_PROJECTION.OBLIQUE.M_PT9_OB_FRONT', 'PRET.G9.COMMUN.OBLIQUE_PROJECTION.OBLIQUE', 'Draws the front face of an oblique drawing slanted and distorted.', '{"question":"In oblique drawing the front face is drawn...","wrong_answer":"At an angle and distorted","correct_answer":"True shape"}'::jsonb, 'The learner thinks every face of a 3D drawing must be slanted.', 'Offer "At an angle and distorted" next to the right answer and ask the question again in a new situation.', 'Draw a block in oblique: the front face is a true rectangle with true sizes; only depth slants.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.COMMUN.OBLIQUE_PROJECTION.OBLIQUE.M_PT9_OB_ANGLE', 'PRET.G9.COMMUN.OBLIQUE_PROJECTION.OBLIQUE', 'Draws the receding (depth) lines at 90 degrees.', '{"question":"At what angle are depth lines usually drawn?","wrong_answer":"90 degrees","correct_answer":"45 degrees"}'::jsonb, 'Right angles are everywhere in drawing, so 90 degrees seems the default.', 'Offer "90 degrees" next to the right answer and ask the question again in a new situation.', 'Use the 45 degree set square on the T-square; draw depth lines at 45 degrees.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.COMMUN.OBLIQUE_PROJECTION.OBLIQUE.M_PT9_OB_CABINET', 'PRET.G9.COMMUN.OBLIQUE_PROJECTION.OBLIQUE', 'Mixes up cabinet (half depth) and cavalier (full depth).', '{"question":"In cabinet projection the depth is...","wrong_answer":"Full size","correct_answer":"Half size"}'::jsonb, 'Cabinet and cavalier sound alike and are learnt together.', 'Offer "Full size" next to the right answer and ask the question again in a new situation.', 'Draw both: cavalier full depth looks too long; cabinet half depth looks right. "Cabinet: cut in half."', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.COMMUN.OBLIQUE_PROJECTION.OBLIQUE_DRAW.M_PT9_OD_CIRCLE_FACE', 'PRET.G9.COMMUN.OBLIQUE_PROJECTION.OBLIQUE_DRAW', 'Puts the face with a circle on a receding side, so the circle becomes a hard ellipse.', '{"question":"A block has a round hole on one face. Which face should go to the front in an oblique drawing?","wrong_answer":"Any face; it does not matter","correct_answer":"The face with the hole, so the circle is drawn true shape with a compass"}'::jsonb, 'The learner draws the block the way it happens to sit on the desk.', 'Offer "Any face; it does not matter" beside "The face with the hole, so the circle is drawn true shape with a compass" and ask the child to choose.', 'Draw the block twice: hole at the front (a compass circle) and hole on the side (a distorted shape). Choose the easier, truer one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.COMMUN.OBLIQUE_PROJECTION.OBLIQUE_DRAW.M_PT9_OD_DEPTH_FULL', 'PRET.G9.COMMUN.OBLIQUE_PROJECTION.OBLIQUE_DRAW', 'Draws the full depth in cabinet oblique instead of half.', '{"question":"A block 60 mm deep is drawn in cabinet oblique. How long are the receding lines?","wrong_answer":"60 mm","correct_answer":"30 mm"}'::jsonb, 'The learner uses the real size everywhere, as in other drawings.', 'Offer "60 mm" beside "30 mm" and ask the child to choose.', 'Draw the same block in cavalier (full depth) and cabinet (half depth); cabinet looks more like the real block.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.COMMUN.OBLIQUE_PROJECTION.OBLIQUE_DRAW.M_PT9_OD_START', 'PRET.G9.COMMUN.OBLIQUE_PROJECTION.OBLIQUE_DRAW', 'Starts an oblique drawing with the receding lines before the front face.', '{"question":"What is drawn first in an oblique drawing?","wrong_answer":"The receding (depth) lines","correct_answer":"The front face, true shape"}'::jsonb, 'The slanting lines look like the hard part, so the learner starts there.', 'Offer "The receding (depth) lines" beside "The front face, true shape" and ask the child to choose.', 'Draw the front face first with true sizes, then project receding lines from each corner at 45 degrees.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.COMMUN.OBLIQUE_PROJECTION.OBLIQUE_DRAW.M_PT9_OD_CONVERGE', 'PRET.G9.COMMUN.OBLIQUE_PROJECTION.OBLIQUE_DRAW', 'Draws receding lines that meet at a point, as in a picture with perspective.', '{"question":"How are all the receding lines in an oblique drawing drawn?","wrong_answer":"Meeting at a point in the distance","correct_answer":"Parallel, all at the same angle"}'::jsonb, 'Pictures and photographs show lines meeting in the distance.', 'Offer "Meeting at a point in the distance" beside "Parallel, all at the same angle" and ask the child to choose.', 'Use the 45 degree set square on the T-square for every receding line; they stay parallel.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.COMMUN.OBLIQUE_PROJECTION.OBLIQUE.M_PT9_OB_ISOMETRIC', 'PRET.G9.COMMUN.OBLIQUE_PROJECTION.OBLIQUE', 'Mixes up oblique and isometric projection.', '{"question":"Which projection draws the front face true shape with receding lines at 45 degrees?","wrong_answer":"Isometric","correct_answer":"Oblique"}'::jsonb, 'Both are pictorial drawings that show three faces.', 'Offer "Isometric" beside "Oblique" and ask the child to choose.', 'Draw the same block in isometric (30 degree lines both ways, no true face) and in oblique (true front, 45 degree depth); compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.COMMUN.VISUAL_PROGRAMMING.VISUAL_APPS.M_PT9_VA_USE', 'PRET.G9.COMMUN.VISUAL_PROGRAMMING.VISUAL_APPS', 'Thinks visual programming only makes games, not tools that solve real problems.', '{"question":"Which problem could a learner solve with a visual programming application?","wrong_answer":"None; it only makes games","correct_answer":"A revision quiz, a price calculator for a kiosk, or a counter for the school gate"}'::jsonb, 'The learner has used Scratch only for games and animations.', 'Offer "None; it only makes games" beside "A revision quiz, a price calculator for a kiosk, or a counter for the school gate" and ask the child to choose.', 'List real problems at school a small app could help with: a revision quiz, a price calculator, a gate counter.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.COMMUN.VISUAL_PROGRAMMING.VISUAL_APPS.M_PT9_VA_BLOCK', 'PRET.G9.COMMUN.VISUAL_PROGRAMMING.VISUAL_APPS', 'Thinks every line of a visual program must be typed.', '{"question":"How is a program built in visual programming?","wrong_answer":"By typing every line","correct_answer":"By joining blocks"}'::jsonb, 'Films show programmers typing fast, so all programming seems to be typing.', 'Offer "By typing every line" next to the right answer and ask the question again in a new situation.', 'Build a short program by dragging blocks only; nothing is typed but numbers and words in the blocks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.COMMUN.VISUAL_PROGRAMMING.VISUAL_APPS.M_PT9_VA_SOLVE', 'PRET.G9.COMMUN.VISUAL_PROGRAMMING.VISUAL_APPS', 'Thinks a program works the first time, so testing and debugging are not needed.', '{"question":"A learner''s quiz app gives the wrong score. What should she do?","wrong_answer":"Start a new app from the beginning","correct_answer":"Test it step by step to find and fix the bug"}'::jsonb, 'The program ran once, so the learner thinks it is finished.', 'Offer "Start a new app from the beginning" beside "Test it step by step to find and fix the bug" and ask the child to choose.', 'Show a quiz that adds the score wrongly; step through it to find and fix the bug.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.COMMUN.VISUAL_PROGRAMMING.VP_APP_BUILD.M_PT9_VB_PLAN', 'PRET.G9.COMMUN.VISUAL_PROGRAMMING.VP_APP_BUILD', 'Starts dragging blocks before stating the problem or planning the steps.', '{"question":"What is the first step in creating an app with a visual programming application?","wrong_answer":"Drag blocks until something works","correct_answer":"State the problem and plan the steps"}'::jsonb, 'Dragging blocks is the fun part and feels like progress.', 'Offer "Drag blocks until something works" beside "State the problem and plan the steps" and ask the child to choose.', 'Write the problem in one sentence and the steps as a list (an algorithm) before opening the application.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.COMMUN.VISUAL_PROGRAMMING.VP_APP_BUILD.M_PT9_VB_VARIABLE', 'PRET.G9.COMMUN.VISUAL_PROGRAMMING.VP_APP_BUILD', 'Expects a program to remember a changing value, such as a score, without a variable.', '{"question":"A quiz app must keep the score. What is needed?","wrong_answer":"Nothing; the app remembers by itself","correct_answer":"A variable called score that changes by 1 for each right answer"}'::jsonb, 'People remember scores in their heads, so the app seems to as well.', 'Offer "Nothing; the app remembers by itself" beside "A variable called score that changes by 1 for each right answer" and ask the child to choose.', 'Make a variable "score"; show it on the stage; add "change score by 1" after a right answer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.COMMUN.VISUAL_PROGRAMMING.VP_APP_BUILD.M_PT9_VB_RESET', 'PRET.G9.COMMUN.VISUAL_PROGRAMMING.VP_APP_BUILD', 'Forgets to set the score back to zero at the start of each game.', '{"question":"Each new game starts with the last game''s score. What is missing?","wrong_answer":"Nothing; the scores should add up","correct_answer":"Set score to 0 when the green flag is clicked"}'::jsonb, 'The learner tests only one game and never sees the old score carry over.', 'Offer "Nothing; the scores should add up" beside "Set score to 0 when the green flag is clicked" and ask the child to choose.', 'Play two games in a row and watch the score; add "set score to 0" under the green flag.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.COMMUN.VISUAL_PROGRAMMING.VP_APP_BUILD.M_PT9_VB_TEST_ONCE', 'PRET.G9.COMMUN.VISUAL_PROGRAMMING.VP_APP_BUILD', 'Tests a program with one right answer and stops.', '{"question":"How should a quiz app be tested?","wrong_answer":"Try one right answer and stop","correct_answer":"Try right answers, wrong answers and unusual inputs"}'::jsonb, 'The program worked once, so the learner thinks it always will.', 'Offer "Try one right answer and stop" beside "Try right answers, wrong answers and unusual inputs" and ask the child to choose.', 'Swap apps with a partner and try to break each other''s quiz; list the bugs found and fix them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.COMMUN.VISUAL_PROGRAMMING.VISUAL_APPS.M_PT9_VA_AREAS', 'PRET.G9.COMMUN.VISUAL_PROGRAMMING.VISUAL_APPS', 'Thinks visual programming is used only in school lessons.', '{"question":"In which area is visual programming used?","wrong_answer":"Only in school lessons","correct_answer":"Robotics, games, education and simple apps for farming, health or business"}'::jsonb, 'The learner has met it only at school.', 'Offer "Only in school lessons" beside "Robotics, games, education and simple apps for farming, health or business" and ask the child to choose.', 'Show block programming used for robots (such as an educational robot kit) and for app builders; list the areas.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.MATERI.WOOD.WOOD_TYPES.M_PT9_WT_HARD', 'PRET.G9.MATERI.WOOD.WOOD_TYPES', 'Calls pine a hardwood.', '{"question":"Which is a hardwood?","wrong_answer":"Pine","correct_answer":"Mahogany"}'::jsonb, 'Pine is the timber seen most in furniture shops, so it is taken for a hardwood.', 'Offer "Pine" next to the right answer and ask the question again in a new situation.', 'Show a pine cone and needle leaves: pine is a conifer, so it is a softwood.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.MATERI.WOOD.WOOD_TYPES.M_PT9_WT_SOFT', 'PRET.G9.MATERI.WOOD.WOOD_TYPES', 'Calls mvule a softwood.', '{"question":"Which is a softwood?","wrong_answer":"Mvule","correct_answer":"Pine"}'::jsonb, 'Mvule is less familiar and the learner guesses.', 'Offer "Mvule" next to the right answer and ask the question again in a new situation.', 'Mvule is a broad-leaved indigenous tree: a hardwood, dense and durable, used for doors and furniture.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.MATERI.WOOD.WOOD_TYPES.M_PT9_WT_BOARD', 'PRET.G9.MATERI.WOOD.WOOD_TYPES', 'Thinks manufactured boards such as plywood are solid planks.', '{"question":"What is plywood?","wrong_answer":"One solid plank","correct_answer":"A board of glued wood layers"}'::jsonb, 'A board from a hardware shop looks like a plank.', 'Offer "One solid plank" next to the right answer and ask the question again in a new situation.', 'Look at the edge of plywood (layers) and chipboard (chips in glue): manufactured boards, not solid timber.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.MATERI.WOOD.WOOD_PREP.M_PT9_WP_SEASON', 'PRET.G9.MATERI.WOOD.WOOD_PREP', 'Uses freshly cut (green) timber at once, not knowing it shrinks, warps and cracks as it dries.', '{"question":"A fundi makes a door from freshly cut timber. What may happen?","wrong_answer":"Nothing; fresh timber is best","correct_answer":"It may shrink, warp or crack as it dries"}'::jsonb, 'Fresh timber looks clean and strong, so drying seems unnecessary.', 'Offer "Nothing; fresh timber is best" beside "It may shrink, warp or crack as it dries" and ask the child to choose.', 'Weigh a fresh offcut and the same one after two weeks; explain shrinking, warping and cracking as water leaves.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.MATERI.WOOD.WOOD_PREP.M_PT9_WP_ORDER', 'PRET.G9.MATERI.WOOD.WOOD_PREP', 'Puts finishing (varnishing) before converting and seasoning the timber.', '{"question":"After a tree is felled, which step comes next?","wrong_answer":"Varnishing it","correct_answer":"Cross-cutting into logs and sawing them into planks (conversion)"}'::jsonb, 'The learner pictures the finished item and starts from the end.', 'Offer "Varnishing it" beside "Cross-cutting into logs and sawing them into planks (conversion)" and ask the child to choose.', 'Order the steps on cards: felling, cross-cutting, conversion (sawing), seasoning, treating, planing, finishing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.MATERI.WOOD.WOOD_PREP.M_PT9_WP_TREAT', 'PRET.G9.MATERI.WOOD.WOOD_PREP', 'Thinks a preservative is only for colour.', '{"question":"Why are fence posts treated with a preservative?","wrong_answer":"To give them a nice colour","correct_answer":"To protect them from rot, termites and other insects"}'::jsonb, 'Treated timber is often coloured, so treatment seems to be for looks.', 'Offer "To give them a nice colour" beside "To protect them from rot, termites and other insects" and ask the child to choose.', 'Show a treated and an untreated fence post after some years (or photos): rot and termite damage on the untreated one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.MATERI.WOOD.WOOD_TYPES.M_PT9_WT_FEEL', 'PRET.G9.MATERI.WOOD.WOOD_TYPES', 'Thinks hardwood and softwood describe how hard the wood feels.', '{"question":"What decides whether timber is a hardwood or a softwood?","wrong_answer":"How hard it feels","correct_answer":"The kind of tree: broad-leaved trees give hardwoods, cone-bearing trees give softwoods"}'::jsonb, 'The names make the learner judge by hardness.', 'Offer "How hard it feels" beside "The kind of tree: broad-leaved trees give hardwoods, cone-bearing trees give softwoods" and ask the child to choose.', 'Show leaves and seeds: mahogany and mvule (broad leaves) against pine and cypress (needles, cones). Note that some hardwoods are soft.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.MATERI.WOOD.WOOD_PREP.M_PT9_WP_STACK', 'PRET.G9.MATERI.WOOD.WOOD_PREP', 'Stacks timber for air seasoning in a tight pile on the ground.', '{"question":"How is timber stacked for air seasoning?","wrong_answer":"In a tight pile on the ground","correct_answer":"Off the ground on bearers, with sticks between the boards, under a roof"}'::jsonb, 'A tight pile looks tidy and saves space.', 'Offer "In a tight pile on the ground" beside "Off the ground on bearers, with sticks between the boards, under a roof" and ask the child to choose.', 'Draw a seasoning stack: bearers off the ground, stickers between boards so air flows, a roof against rain and sun.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.MATERI.HANDLING_WASTE_MATERIALS.WASTE.M_PT9_WS_BURN', 'PRET.G9.MATERI.HANDLING_WASTE_MATERIALS.WASTE', 'Thinks burning plastic is a safe way to get rid of it.', '{"question":"What should be done with plastic waste?","wrong_answer":"Burn it","correct_answer":"Sort and recycle it"}'::jsonb, 'Burning makes waste disappear quickly, and the smoke is not seen as harm.', 'Offer "Burn it" next to the right answer and ask the question again in a new situation.', 'Explain the harmful smoke from burning plastic; show sorting, reuse and recycling points.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.MATERI.HANDLING_WASTE_MATERIALS.WASTE.M_PT9_WS_ORGANIC', 'PRET.G9.MATERI.HANDLING_WASTE_MATERIALS.WASTE', 'Throws or burns kitchen peelings instead of composting them.', '{"question":"What can be done with kitchen peelings?","wrong_answer":"Burn them","correct_answer":"Make compost"}'::jsonb, 'Peelings look like rubbish, not like something useful.', 'Offer "Burn them" next to the right answer and ask the question again in a new situation.', 'Start a compost pit or heap with kitchen and garden waste; use it in the school garden.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.MATERI.HANDLING_WASTE_MATERIALS.WASTE.M_PT9_WS_SHARP', 'PRET.G9.MATERI.HANDLING_WASTE_MATERIALS.WASTE', 'Puts broken glass loose into the waste bin.', '{"question":"How should broken glass be thrown away?","wrong_answer":"Straight into the bin as it is","correct_answer":"Wrapped in thick paper or cloth, labelled, then put in the bin"}'::jsonb, 'Broken glass seems to be gone once it is in the bin.', 'Offer "Straight into the bin as it is" beside "Wrapped in thick paper or cloth, labelled, then put in the bin" and ask the child to choose.', 'Show how a collector can be cut by loose glass in a bag; wrap it in thick paper or cloth, label it, then put it in the bin.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.MATERI.HANDLING_WASTE_MATERIALS.WASTE.M_PT9_WS_ONE_BIN', 'PRET.G9.MATERI.HANDLING_WASTE_MATERIALS.WASTE', 'Puts all waste in one bin without sorting.', '{"question":"Why is waste sorted into separate bins?","wrong_answer":"There is no need; it all goes to the same place","correct_answer":"So it can be reused, recycled, composted or disposed of safely"}'::jsonb, 'The learner has seen all waste end up at one dump.', 'Offer "There is no need; it all goes to the same place" beside "So it can be reused, recycled, composted or disposed of safely" and ask the child to choose.', 'Run a waste-sorting activity: organic, paper, plastic, glass, metal, hazardous.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.MATERI.HANDLING_WASTE_MATERIALS.WASTE.M_PT9_WS_BATTERY', 'PRET.G9.MATERI.HANDLING_WASTE_MATERIALS.WASTE', 'Throws used dry cells into the rubbish fire.', '{"question":"How should used dry cells (batteries) be disposed of?","wrong_answer":"Burnt with the rubbish","correct_answer":"Kept apart and taken to a collection point"}'::jsonb, 'Batteries are small, so they seem harmless.', 'Offer "Burnt with the rubbish" beside "Kept apart and taken to a collection point" and ask the child to choose.', 'Explain that batteries hold harmful chemicals and can burst in a fire; set up a class battery box for a collection point.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.TOOLS_.HOLDING_TOOLS.HOLDING_TOOLS.M_PT9_HT_VICE', 'PRET.G9.TOOLS_.HOLDING_TOOLS.HOLDING_TOOLS', 'Thinks a bench vice shapes the work rather than holding it.', '{"question":"What does a bench vice do?","wrong_answer":"Bends and shapes the metal by itself","correct_answer":"Holds the work firmly while you cut, file or drill"}'::jsonb, 'The vice sits on the bench where the work is shaped, so it seems to shape it.', 'Offer "Bends and shapes the metal by itself" beside "Holds the work firmly while you cut, file or drill" and ask the child to choose.', 'Hold a strip in the vice and file it: the vice holds, the file shapes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.TOOLS_.HOLDING_TOOLS.HOLDING_TOOLS.M_PT9_HT_CLAMP', 'PRET.G9.TOOLS_.HOLDING_TOOLS.HOLDING_TOOLS', 'Uses pliers to hold glued work instead of a clamp.', '{"question":"Which tool holds two glued pieces of wood together while the glue sets?","wrong_answer":"A pair of pliers","correct_answer":"A G-clamp"}'::jsonb, 'Pliers are the gripping tool the learner knows from home.', 'Offer "A pair of pliers" beside "A G-clamp" and ask the child to choose.', 'Glue two pieces and clamp them with a G-clamp; show pliers cannot hold them evenly for hours.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.TOOLS_.HOLDING_TOOLS.HOLDING_TOOLS.M_PT9_HT_CARE', 'PRET.G9.TOOLS_.HOLDING_TOOLS.HOLDING_TOOLS', 'Hammers a vice handle to tighten it, which bends the handle and strains the screw.', '{"question":"How should a bench vice be cared for?","wrong_answer":"Hammer the handle to tighten it fully","correct_answer":"Clean it, oil the screw and tighten by hand only"}'::jsonb, 'A tighter grip seems better, and a hammer gives more force.', 'Offer "Hammer the handle to tighten it fully" beside "Clean it, oil the screw and tighten by hand only" and ask the child to choose.', 'Show a bent vice handle; tighten by hand only, clean out chips and oil the screw.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.TOOLS_.HOLDING_TOOLS.HOLD_USE.M_PT9_HU_HIGH', 'PRET.G9.TOOLS_.HOLDING_TOOLS.HOLD_USE', 'Clamps work high above the vice jaws, so it vibrates and bends when filed or sawn.', '{"question":"When filing a piece of metal held in a vice, how much should stick out above the jaws?","wrong_answer":"As much as possible, so it is easy to reach","correct_answer":"Only a little, so it does not vibrate or bend"}'::jsonb, 'More of the work showing seems easier to work on.', 'Offer "As much as possible, so it is easy to reach" beside "Only a little, so it does not vibrate or bend" and ask the child to choose.', 'File a strip held high and then held low; hear the chatter and feel the bend in the first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.TOOLS_.HOLDING_TOOLS.HOLD_USE.M_PT9_HU_PACKING', 'PRET.G9.TOOLS_.HOLDING_TOOLS.HOLD_USE', 'Clamps a finished wooden piece straight in steel jaws, which dents it.', '{"question":"How do you hold a finished wooden piece in a metal vice without marking it?","wrong_answer":"Tighten it straight in the steel jaws","correct_answer":"Put soft packing (wood scraps or soft jaws) between the jaws and the work"}'::jsonb, 'The learner thinks only of holding tight, not of the surface.', 'Offer "Tighten it straight in the steel jaws" beside "Put soft packing (wood scraps or soft jaws) between the jaws and the work" and ask the child to choose.', 'Clamp a scrap with and without packing; compare the marks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.TOOLS_.HOLDING_TOOLS.HOLD_USE.M_PT9_HU_DRILL_HAND', 'PRET.G9.TOOLS_.HOLDING_TOOLS.HOLD_USE', 'Holds a small plate by hand while it is drilled.', '{"question":"A small metal plate is to be drilled. How is it held?","wrong_answer":"By hand, pressed down firmly","correct_answer":"In a machine vice or clamped to the table"}'::jsonb, 'Holding by hand feels quick and firm enough.', 'Offer "By hand, pressed down firmly" beside "In a machine vice or clamped to the table" and ask the child to choose.', 'Explain that a drill can catch and spin the plate into the hand; always clamp. Shown by the teacher only.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.TOOLS_.HOLDING_TOOLS.HOLD_USE.M_PT9_HU_SUPPORT', 'PRET.G9.TOOLS_.HOLDING_TOOLS.HOLD_USE', 'Holds a long plank by one end in the vice with nothing under the other end.', '{"question":"A long plank is held in the vice at one end for planing. What else is needed?","wrong_answer":"Nothing; the vice holds it","correct_answer":"Support at the other end: a bench stop, a second clamp or a helper"}'::jsonb, 'The vice looks strong enough to hold anything.', 'Offer "Nothing; the vice holds it" beside "Support at the other end: a bench stop, a second clamp or a helper" and ask the child to choose.', 'Show how a long plank sags and swings; add a support and plane again.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.TOOLS_.HOLDING_TOOLS.HOLDING_TOOLS.M_PT9_HT_TONGS', 'PRET.G9.TOOLS_.HOLDING_TOOLS.HOLDING_TOOLS', 'Holds hot metal with ordinary pliers or by hand instead of tongs.', '{"question":"Which tool holds a piece of red-hot metal?","wrong_answer":"Ordinary pliers","correct_answer":"Tongs"}'::jsonb, 'Pliers grip well, so they seem right for anything.', 'Offer "Ordinary pliers" beside "Tongs" and ask the child to choose.', 'Show blacksmith''s tongs and their long handles; explain heat travels up short pliers to the hand.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.TOOLS_.DRIVING_TOOLS.DRIVING_TOOLS.M_PT9_DT_HAMMER', 'PRET.G9.TOOLS_.DRIVING_TOOLS.DRIVING_TOOLS', 'Thinks a hammer is used to drive screws.', '{"question":"What does a hammer drive?","wrong_answer":"Screws","correct_answer":"Nails"}'::jsonb, 'Screws and nails both fix wood, so one tool seems to drive both.', 'Offer "Screws" next to the right answer and ask the question again in a new situation.', 'Hammer a screw into scrap and see the wood split and the screw hold badly; screws are turned.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.TOOLS_.DRIVING_TOOLS.DRIVING_TOOLS.M_PT9_DT_SCREWDRIVER', 'PRET.G9.TOOLS_.DRIVING_TOOLS.DRIVING_TOOLS', 'Uses a flat screwdriver on a cross-head screw.', '{"question":"A cross-head screw needs...","wrong_answer":"A flat screwdriver","correct_answer":"A cross-head screwdriver"}'::jsonb, 'A flat screwdriver is the one most homes have.', 'Offer "A flat screwdriver" next to the right answer and ask the question again in a new situation.', 'Match screw heads (slotted, cross-head) to screwdrivers; a wrong tip slips and damages the head.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.TOOLS_.DRIVING_TOOLS.DRIVING_TOOLS.M_PT9_DT_SPANNER', 'PRET.G9.TOOLS_.DRIVING_TOOLS.DRIVING_TOOLS', 'Uses pliers instead of a spanner to tighten nuts.', '{"question":"Which tool tightens a nut on a bolt?","wrong_answer":"Pliers","correct_answer":"A spanner of the right size"}'::jsonb, 'Pliers grip anything, so they seem fine for nuts.', 'Offer "Pliers" beside "A spanner of the right size" and ask the child to choose.', 'Turn a nut with pliers and with a spanner; the pliers slip and round off the corners.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.TOOLS_.DRIVING_TOOLS.DRIVE_USE.M_PT9_DU_GRIP', 'PRET.G9.TOOLS_.DRIVING_TOOLS.DRIVE_USE', 'Holds a hammer close to its head when driving a nail.', '{"question":"Where should a hammer be held for driving a nail?","wrong_answer":"Close to the head, for control","correct_answer":"Near the end of the handle, for a stronger, straighter blow"}'::jsonb, 'Holding near the head feels more controlled.', 'Offer "Close to the head, for control" beside "Near the end of the handle, for a stronger, straighter blow" and ask the child to choose.', 'Drive two nails, one with each grip; compare how many blows and how straight. The handle works as a lever.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.TOOLS_.DRIVING_TOOLS.DRIVE_USE.M_PT9_DU_START_NAIL', 'PRET.G9.TOOLS_.DRIVING_TOOLS.DRIVE_USE', 'Holds a nail with the fingers and hits it hard from the first blow.', '{"question":"How do you start a nail safely?","wrong_answer":"Hold it with your fingers and hit it hard","correct_answer":"Tap it lightly to start it, then move your fingers away"}'::jsonb, 'Hitting hard seems to get the job done fastest.', 'Offer "Hold it with your fingers and hit it hard" beside "Tap it lightly to start it, then move your fingers away" and ask the child to choose.', 'Start nails with light taps; for small nails hold them with pliers or through a piece of card.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.TOOLS_.DRIVING_TOOLS.DRIVE_USE.M_PT9_DU_SPANNER_FIT', 'PRET.G9.TOOLS_.DRIVING_TOOLS.DRIVE_USE', 'Uses a spanner a little too big for the nut.', '{"question":"A spanner is slightly too big for a nut. What happens if you use it?","wrong_answer":"Nothing; it still turns the nut","correct_answer":"It slips, rounds off the nut and can hurt your hand"}'::jsonb, 'A spanner that goes on seems to fit.', 'Offer "Nothing; it still turns the nut" beside "It slips, rounds off the nut and can hurt your hand" and ask the child to choose.', 'Try a loose spanner on an old nut and see the corners round off; always pick the size that fits.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.TOOLS_.DRIVING_TOOLS.DRIVE_USE.M_PT9_DU_SCREWDRIVER_SIZE', 'PRET.G9.TOOLS_.DRIVING_TOOLS.DRIVE_USE', 'Uses any screwdriver whose tip goes into the slot, even a small one.', '{"question":"What size of screwdriver blade should you use for a screw?","wrong_answer":"Any size that goes into the slot","correct_answer":"One that fills the slot fully"}'::jsonb, 'A small tip slides in easily, so it seems right.', 'Offer "Any size that goes into the slot" beside "One that fills the slot fully" and ask the child to choose.', 'Turn a tight screw with a small and a correct tip; the small one slips and damages the slot.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.TOOLS_.DRIVING_TOOLS.DRIVE_USE.M_PT9_DU_PUSH', 'PRET.G9.TOOLS_.DRIVING_TOOLS.DRIVE_USE', 'Pushes a spanner away from the body to loosen a tight nut.', '{"question":"Should you push or pull a spanner on a tight nut?","wrong_answer":"Push it away from you hard","correct_answer":"Pull it towards you, standing steady"}'::jsonb, 'Pushing feels stronger.', 'Offer "Push it away from you hard" beside "Pull it towards you, standing steady" and ask the child to choose.', 'Show what happens when a pushed spanner slips: the hand hits the metal. Pull, with feet firm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.TOOLS_.DRIVING_TOOLS.DRIVING_TOOLS.M_PT9_DT_MALLET', 'PRET.G9.TOOLS_.DRIVING_TOOLS.DRIVING_TOOLS', 'Strikes a wooden-handled chisel with a steel hammer instead of a mallet.', '{"question":"What is used to strike a chisel with a wooden handle?","wrong_answer":"A steel claw hammer","correct_answer":"A wooden mallet"}'::jsonb, 'A hammer is the striking tool the learner knows.', 'Offer "A steel claw hammer" beside "A wooden mallet" and ask the child to choose.', 'Show a chisel handle split by a hammer; a mallet''s wide wooden face strikes without damage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.TOOLS_.PROJECT.PROJECT_STEPS.M_PT9_PJ_FIRST', 'PRET.G9.TOOLS_.PROJECT.PROJECT_STEPS', 'Starts a project by making an item before identifying a problem.', '{"question":"What is the first step of a project?","wrong_answer":"Make the item","correct_answer":"Identify a problem"}'::jsonb, 'Making is the exciting part, so it feels like the first step.', 'Offer "Make the item" next to the right answer and ask the question again in a new situation.', 'Order the project steps on cards: identify a problem, choose an item, plan, make, test, evaluate.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.TOOLS_.PROJECT.PROJECT_STEPS.M_PT9_PJ_TEST', 'PRET.G9.TOOLS_.PROJECT.PROJECT_STEPS', 'Hands in an item without testing it.', '{"question":"After making the item, what comes next?","wrong_answer":"Hand it in straight away","correct_answer":"Test it and improve it if needed"}'::jsonb, 'A finished item feels like the end of the project.', 'Offer "Hand it in straight away" beside "Test it and improve it if needed" and ask the child to choose.', 'Test a made item against its purpose (does the rack hold the shoes?) and improve it before handing in.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.TOOLS_.PROJECT.PROJECT_STEPS.M_PT9_PJ_MATERIAL', 'PRET.G9.TOOLS_.PROJECT.PROJECT_STEPS', 'Thinks a project needs costly imported materials.', '{"question":"Which materials are best for a school project?","wrong_answer":"Only costly imported ones","correct_answer":"Locally available ones"}'::jsonb, 'Costly materials look more professional.', 'Offer "Only costly imported ones" next to the right answer and ask the question again in a new situation.', 'List local and waste materials (offcuts, bottles, sisal, scrap metal) and items made from them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.TOOLS_.PROJECT.PROJECT_PLAN.M_PT9_PP_NO_DRAWING', 'PRET.G9.TOOLS_.PROJECT.PROJECT_PLAN', 'Starts cutting materials without a sketch or working drawing.', '{"question":"What should you prepare before you start making a project item?","wrong_answer":"Nothing; start cutting the materials","correct_answer":"A sketch and a working drawing with sizes"}'::jsonb, 'Making feels like the real work and drawing like a delay.', 'Offer "Nothing; start cutting the materials" beside "A sketch and a working drawing with sizes" and ask the child to choose.', 'Show two shelves: one made from a drawing, one without; compare the fit and the waste.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.TOOLS_.PROJECT.PROJECT_PLAN.M_PT9_PP_NO_COST', 'PRET.G9.TOOLS_.PROJECT.PROJECT_PLAN', 'Skips the materials and cost list.', '{"question":"Why list the materials and their cost before starting?","wrong_answer":"It is a waste of time","correct_answer":"To know what to get, what it will cost and to avoid running out"}'::jsonb, 'The learner thinks materials can be found as needed.', 'Offer "It is a waste of time" beside "To know what to get, what it will cost and to avoid running out" and ask the child to choose.', 'Cost a small item together (timber, nails, glue, varnish); compare with the money available.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.TOOLS_.PROJECT.PROJECT_PLAN.M_PT9_PP_FINISH_FIRST', 'PRET.G9.TOOLS_.PROJECT.PROJECT_PLAN', 'Varnishes or paints parts before cutting and joining them.', '{"question":"When is a wooden item painted or varnished?","wrong_answer":"Before cutting and joining the parts","correct_answer":"After making and sanding, as the last step"}'::jsonb, 'Finished-looking parts feel like progress.', 'Offer "Before cutting and joining the parts" beside "After making and sanding, as the last step" and ask the child to choose.', 'Show how glue does not stick to varnish and cutting damages the finish; write the order of operations.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.TOOLS_.PROJECT.PROJECT_PLAN.M_PT9_PP_LOOKS_ONLY', 'PRET.G9.TOOLS_.PROJECT.PROJECT_PLAN', 'Evaluates the finished item only by how it looks.', '{"question":"How is a finished project item evaluated?","wrong_answer":"By whether it looks nice","correct_answer":"By whether it solves the problem it was made for, and how it could be improved"}'::jsonb, 'Looks are what people praise first.', 'Offer "By whether it looks nice" beside "By whether it solves the problem it was made for, and how it could be improved" and ask the child to choose.', 'Return to the problem statement; test the item against it (does the shoe rack hold 20 pairs?) and list improvements.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.TOOLS_.PROJECT.PROJECT_STEPS.M_PT9_PJ_TOO_BIG', 'PRET.G9.TOOLS_.PROJECT.PROJECT_STEPS', 'Chooses a problem far too big for the skills, time and materials available.', '{"question":"Which problem suits a Grade 9 Pre-Technical project?","wrong_answer":"Build a new road for the village","correct_answer":"Make a shoe rack that keeps classroom shoes off the floor"}'::jsonb, 'Big problems feel more important and impressive.', 'Offer "Build a new road for the village" beside "Make a shoe rack that keeps classroom shoes off the floor" and ask the child to choose.', 'Check each idea against skills, tools, time and money; shrink a big idea into a small item that helps.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.ENTREP.FINANCIAL_SERVICES.FIN_TYPES.M_PT9_FT_NAME', 'PRET.G9.ENTREP.FINANCIAL_SERVICES.FIN_TYPES', 'Thinks any business that handles a lot of cash is a financial institution.', '{"question":"Which of these is a financial institution?","wrong_answer":"A wholesale shop","correct_answer":"A SACCO"}'::jsonb, 'Any big business that handles a lot of cash seems like a financial institution.', 'Offer "A wholesale shop" beside "A SACCO" and ask the child to choose.', 'Sort places by what they do: deal in money (banks, SACCOs, insurers, microfinance) or sell goods (shops, wholesalers).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.ENTREP.FINANCIAL_SERVICES.FIN_TYPES.M_PT9_FT_CENTRAL', 'PRET.G9.ENTREP.FINANCIAL_SERVICES.FIN_TYPES', 'Thinks the Central Bank of Kenya serves ordinary customers like a commercial bank.', '{"question":"What does the Central Bank of Kenya do?","wrong_answer":"Keeps savings accounts for ordinary people","correct_answer":"Issues currency and supervises banks"}'::jsonb, '"Bank" in the name makes the learner think of savings accounts.', 'Offer "Keeps savings accounts for ordinary people" beside "Issues currency and supervises banks" and ask the child to choose.', 'Explain the Central Bank is the bankers'' bank: issues currency, supervises banks, keeps the government''s account.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.ENTREP.FINANCIAL_SERVICES.FIN_TYPES.M_PT9_FT_INSURE', 'PRET.G9.ENTREP.FINANCIAL_SERVICES.FIN_TYPES', 'Thinks a commercial bank gives cover against loss.', '{"question":"Which gives cover against loss?","wrong_answer":"A commercial bank","correct_answer":"An insurance company"}'::jsonb, 'Banks and insurers both deal with money and are in the same buildings in town.', 'Offer "A commercial bank" next to the right answer and ask the question again in a new situation.', 'Compare a bank (keeps savings, lends) and an insurer (pays out after a loss, in return for premiums).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.ENTREP.FINANCIAL_SERVICES.FIN_SERVICES.M_PT9_FV_LOAN', 'PRET.G9.ENTREP.FINANCIAL_SERVICES.FIN_SERVICES', 'Thinks a loan is repaid without interest.', '{"question":"What must be repaid on a loan?","wrong_answer":"Only the amount borrowed","correct_answer":"The amount borrowed plus interest"}'::jsonb, 'The learner thinks paying back what was borrowed is fair and complete.', 'Offer "Only the amount borrowed" beside "The amount borrowed plus interest" and ask the child to choose.', 'Work a small example: borrow 1,000 at 10 percent for a year; repay 1,100. Interest is the cost of borrowing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.ENTREP.FINANCIAL_SERVICES.FIN_SERVICES.M_PT9_FV_SAVE', 'PRET.G9.ENTREP.FINANCIAL_SERVICES.FIN_SERVICES', 'Thinks savings are just as safe kept at home.', '{"question":"Why keep savings in a bank or SACCO rather than at home?","wrong_answer":"There is no difference","correct_answer":"It is safer and may earn interest"}'::jsonb, 'Money at home feels close and in control.', 'Offer "There is no difference" beside "It is safer and may earn interest" and ask the child to choose.', 'List what can happen to cash at home (theft, fire, spending it); savings in a bank or SACCO are safer and may earn interest.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.ENTREP.FINANCIAL_SERVICES.FIN_SERVICES.M_PT9_FV_SERVICE', 'PRET.G9.ENTREP.FINANCIAL_SERVICES.FIN_SERVICES', 'Thinks a commercial bank sells goods such as farm inputs.', '{"question":"Which is a service offered by a commercial bank?","wrong_answer":"Selling farm inputs","correct_answer":"Keeping savings, giving loans and transferring money"}'::jsonb, 'The learner thinks a bank sells things like a shop.', 'Offer "Selling farm inputs" beside "Keeping savings, giving loans and transferring money" and ask the child to choose.', 'List bank services: savings and current accounts, loans, money transfer, safe keeping, advice, foreign exchange.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.ENTREP.FINANCIAL_SERVICES.FIN_TYPES.M_PT9_FT_SACCO', 'PRET.G9.ENTREP.FINANCIAL_SERVICES.FIN_TYPES', 'Thinks a SACCO is the same as a commercial bank owned by shareholders for profit.', '{"question":"How is a SACCO different from a commercial bank?","wrong_answer":"It is the same; both are owned by shareholders for profit","correct_answer":"Its members save together and lend to one another, and the members own it"}'::jsonb, 'Both take savings and give loans, so they look the same.', 'Offer "It is the same; both are owned by shareholders for profit" beside "Its members save together and lend to one another, and the members own it" and ask the child to choose.', 'Draw who owns each: a bank (shareholders) and a SACCO (its members); list what members gain.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.ENTREP.FINANCIAL_SERVICES.FIN_SERVICES.M_PT9_FV_PREMIUM', 'PRET.G9.ENTREP.FINANCIAL_SERVICES.FIN_SERVICES', 'Thinks an insurance premium is a saving returned at the end of the year if nothing goes wrong.', '{"question":"A trader pays a premium to insure her shop, and no loss happens that year. What happens to the premium?","wrong_answer":"She gets it all back at the end of the year","correct_answer":"It is not returned; it paid for the cover against loss"}'::jsonb, 'Paying in regularly feels like saving.', 'Offer "She gets it all back at the end of the year" beside "It is not returned; it paid for the cover against loss" and ask the child to choose.', 'Compare a savings account (money kept and returned) with insurance (many pay in, those who suffer a loss are paid).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.ENTREP.GOVERNMENT_AND_BUSINESS.GOV_BUSINESS.M_PT9_GV_PROTECT', 'PRET.G9.ENTREP.GOVERNMENT_AND_BUSINESS.GOV_BUSINESS', 'Thinks government rules exist only to slow business down.', '{"question":"Why does the government inspect weighing scales in shops?","wrong_answer":"To slow businesses down","correct_answer":"To protect customers from being cheated"}'::jsonb, 'Rules feel like obstacles to the learner, never like protection.', 'Offer "To slow businesses down" beside "To protect customers from being cheated" and ask the child to choose.', 'Discuss weights and measures checks, food inspection and standards marks: they protect customers and honest traders.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.ENTREP.GOVERNMENT_AND_BUSINESS.GOV_BUSINESS.M_PT9_GV_LICENCE', 'PRET.G9.ENTREP.GOVERNMENT_AND_BUSINESS.GOV_BUSINESS', 'Thinks a small business can operate without a licence or permit.', '{"question":"What do businesses need to operate legally?","wrong_answer":"No licence at all","correct_answer":"A licence"}'::jsonb, 'Small traders around the learner sometimes work without permits.', 'Offer "No licence at all" next to the right answer and ask the question again in a new situation.', 'Show a single business permit from the county and list what it allows; trading without it risks fines and closure.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.ENTREP.GOVERNMENT_AND_BUSINESS.GOV_BUSINESS.M_PT9_GV_HELP', 'PRET.G9.ENTREP.GOVERNMENT_AND_BUSINESS.GOV_BUSINESS', 'Thinks government help means telling businesses what to sell.', '{"question":"How does the government help businesses?","wrong_answer":"By telling them what to sell","correct_answer":"By building roads, providing power, and giving loans and training"}'::jsonb, 'The learner pictures government help as control.', 'Offer "By telling them what to sell" beside "By building roads, providing power, and giving loans and training" and ask the child to choose.', 'List what government provides for business: roads, power, water, security, loans and training (youth and women funds), trade fairs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.ENTREP.GOVERNMENT_AND_BUSINESS.TAXES.M_PT9_TX_VAT', 'PRET.G9.ENTREP.GOVERNMENT_AND_BUSINESS.TAXES', 'Thinks VAT is a tax on a worker''s salary.', '{"question":"What is VAT charged on?","wrong_answer":"A worker''s salary","correct_answer":"Goods and services when they are bought"}'::jsonb, 'All taxes sound alike, and income is the tax adults talk about.', 'Offer "A worker''s salary" beside "Goods and services when they are bought" and ask the child to choose.', 'Find VAT on a supermarket receipt: it is charged on goods and services when they are bought.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.ENTREP.GOVERNMENT_AND_BUSINESS.TAXES.M_PT9_TX_USE', 'PRET.G9.ENTREP.GOVERNMENT_AND_BUSINESS.TAXES', 'Thinks taxes pay only the people who collect them.', '{"question":"What are taxes used for?","wrong_answer":"Paying the tax collectors only","correct_answer":"Public services such as roads, schools, hospitals and security"}'::jsonb, 'The learner does not see where tax money goes.', 'Offer "Paying the tax collectors only" beside "Public services such as roads, schools, hospitals and security" and ask the child to choose.', 'List public services near school (roads, the school, the health centre, security) and say taxes pay for them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.ENTREP.GOVERNMENT_AND_BUSINESS.TAXES.M_PT9_TX_EGOV', 'PRET.G9.ENTREP.GOVERNMENT_AND_BUSINESS.TAXES', 'Thinks any website, such as social media, is an e-Government service.', '{"question":"Which online service lets a business owner apply for permits or file tax returns?","wrong_answer":"A social media page","correct_answer":"eCitizen or KRA iTax"}'::jsonb, 'Any website seems like a government service.', 'Offer "A social media page" beside "eCitizen or KRA iTax" and ask the child to choose.', 'Show eCitizen (permits, licences) and KRA iTax (tax returns) pages; compare with social media.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.ENTREP.GOVERNMENT_AND_BUSINESS.GOV_BUSINESS.M_PT9_GV_STATE_CORP', 'PRET.G9.ENTREP.GOVERNMENT_AND_BUSINESS.GOV_BUSINESS', 'Thinks the government never runs any business itself.', '{"question":"Which is a way the government takes part in business?","wrong_answer":"It never runs any business","correct_answer":"It runs state corporations such as the Kenya Ports Authority"}'::jsonb, 'The learner thinks of government only as rule-maker.', 'Offer "It never runs any business" beside "It runs state corporations such as the Kenya Ports Authority" and ask the child to choose.', 'List state corporations that provide services for a fee (ports, railways, water companies) and why government runs them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.ENTREP.GOVERNMENT_AND_BUSINESS.TAXES.M_PT9_TX_PAYE', 'PRET.G9.ENTREP.GOVERNMENT_AND_BUSINESS.TAXES', 'Thinks PAYE is an indirect tax.', '{"question":"Is PAYE (Pay As You Earn) a direct or an indirect tax?","wrong_answer":"Indirect","correct_answer":"Direct, taken from a worker''s income"}'::jsonb, 'The tax is taken by the employer, so it seems indirect.', 'Offer "Indirect" beside "Direct, taken from a worker''s income" and ask the child to choose.', 'Sort taxes: direct (on income or profit: PAYE, corporation tax) and indirect (on spending: VAT, excise duty, customs duty).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.ENTREP.BUSINESS_PLAN.BUSINESS_PLAN.M_PT9_BPL_IMPORT', 'PRET.G9.ENTREP.BUSINESS_PLAN.BUSINESS_PLAN', 'Thinks a business plan is a waste of time.', '{"question":"Why write a business plan?","wrong_answer":"It is a waste of time","correct_answer":"It guides the owner and helps get a loan"}'::jsonb, 'Planning feels slower than starting to sell.', 'Offer "It is a waste of time" next to the right answer and ask the question again in a new situation.', 'Compare two traders: one who planned costs and market and one who did not; list what went wrong for the second.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.ENTREP.BUSINESS_PLAN.BUSINESS_PLAN.M_PT9_BPL_PART', 'PRET.G9.ENTREP.BUSINESS_PLAN.BUSINESS_PLAN', 'Leaves out the market analysis, thinking the product alone is enough.', '{"question":"A business plan describes the product. What else must it show?","wrong_answer":"Nothing; a good product sells itself","correct_answer":"The market: the customers and the competitors"}'::jsonb, 'A good product feels like enough to make a business work.', 'Offer "Nothing; a good product sells itself" beside "The market: the customers and the competitors" and ask the child to choose.', 'Read a short plan with no market section; ask who will buy and who else sells the same thing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.ENTREP.BUSINESS_PLAN.BUSINESS_PLAN.M_PT9_BPL_MONEY', 'PRET.G9.ENTREP.BUSINESS_PLAN.BUSINESS_PLAN', 'Thinks the title page shows the costs and income.', '{"question":"Which part shows costs and income?","wrong_answer":"The title page","correct_answer":"The money plan"}'::jsonb, 'The title page comes first and looks the most important.', 'Offer "The title page" next to the right answer and ask the question again in a new situation.', 'Point to the financial plan in a template: start-up costs, expected sales, costs and profit.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.ENTREP.BUSINESS_PLAN.BP_TEMPLATE.M_PT9_BT_STARTUP', 'PRET.G9.ENTREP.BUSINESS_PLAN.BP_TEMPLATE', 'Counts only the first stock as start-up capital, forgetting equipment and the licence.', '{"question":"A learner plans a juice stall. Which costs go into the start-up capital?","wrong_answer":"Only the fruit","correct_answer":"The blender, cups, licence and the first stock of fruit"}'::jsonb, 'The stock is what will be sold, so it feels like the whole cost.', 'Offer "Only the fruit" beside "The blender, cups, licence and the first stock of fruit" and ask the child to choose.', 'List everything needed before the first sale; sort it into equipment, permits and stock.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.ENTREP.BUSINESS_PLAN.BP_TEMPLATE.M_PT9_BT_PROFIT', 'PRET.G9.ENTREP.BUSINESS_PLAN.BP_TEMPLATE', 'Writes projected sales as the projected profit.', '{"question":"Projected sales 30,000 shillings a month, projected costs 22,000. What is the projected profit?","wrong_answer":"30,000 shillings","correct_answer":"8,000 shillings"}'::jsonb, 'Sales are the biggest, most hopeful number in the plan.', 'Offer "30,000 shillings" beside "8,000 shillings" and ask the child to choose.', 'Write profit = sales - costs in the template row itself; fill it in for three businesses.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.ENTREP.BUSINESS_PLAN.BP_TEMPLATE.M_PT9_BT_SUMMARY', 'PRET.G9.ENTREP.BUSINESS_PLAN.BP_TEMPLATE', 'Writes the executive summary first, before the rest of the plan exists.', '{"question":"When is the executive summary of a business plan written?","wrong_answer":"First, before any other part","correct_answer":"Last, after the other parts, though it is placed first"}'::jsonb, 'It comes first in the plan, so it seems to be written first.', 'Offer "First, before any other part" beside "Last, after the other parts, though it is placed first" and ask the child to choose.', 'Try to summarise an empty plan; then fill the parts and summarise. Only the second works.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.ENTREP.BUSINESS_PLAN.BP_TEMPLATE.M_PT9_BT_COMPETITORS', 'PRET.G9.ENTREP.BUSINESS_PLAN.BP_TEMPLATE', 'Writes "no competitors" when similar businesses are close by.', '{"question":"A learner writes \"no competitors\" for a mandazi stall beside two kiosks that sell mandazi. What is wrong?","wrong_answer":"Nothing; competitors need not be in a plan","correct_answer":"The kiosks are competitors and must be named, with how the stall will be different"}'::jsonb, 'Admitting competitors seems to make the plan weaker.', 'Offer "Nothing; competitors need not be in a plan" beside "The kiosks are competitors and must be named, with how the stall will be different" and ask the child to choose.', 'Walk the market (or a map) and list every seller of the same goods; write one way the new stall will be different.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G9.ENTREP.BUSINESS_PLAN.BUSINESS_PLAN.M_PT9_BPL_ONCE', 'PRET.G9.ENTREP.BUSINESS_PLAN.BUSINESS_PLAN', 'Thinks a business plan is written once and never changed.', '{"question":"A business plan was written a year ago and prices have changed. What should the owner do?","wrong_answer":"Keep it as it is; plans are written once","correct_answer":"Review and update the plan"}'::jsonb, 'A written plan feels finished, like a handed-in assignment.', 'Offer "Keep it as it is; plans are written once" beside "Review and update the plan" and ask the child to choose.', 'Change one price in a plan and see how the profit changes; plan a review each term.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
